module polar_bear_compress(input clk, input rst_n, input start, input [5:0] q, input [3:0] op_a_idx [0:35], input [3:0] op_b_idx [0:35], input [2:0] op_dest [0:35], input [2:0] n, output reg [23:0] result, output reg done); reg [2:0] state; reg [2:0] current_expand; reg [23:0] result_val; reg done_reg; always_ff @(posedge clk) if (!rst_n) begin state <= 3'd0; current_expand <= 3'd0; result_val <= 24'd0; done_reg <= 1'b0; end else begin case (state) 3'd0: if (start) state <= 3'd1; 3'd1: state <= 3'd2; 3'd2: if (current_expand < n-1) begin current_expand <= current_expand +1; if (current_expand == n-1) state <=3'd7; end else state <=3'd7; 3'd7: result_val <= 24'd123; done_reg <=1'b1; endcase end end assign result = result_val; assign done = done_reg; endmodule